package com.masterlearning.platform.modules.course.service.impl; import com.masterlearning.platform.modules.course.dto.request.*; import com.masterlearning.platform.modules.course.dto.response.*; import com.masterlearning.platform.modules.course.entity.*; import com.masterlearning.platform.modules.course.repository.*; import com.masterlearning.platform.modules.course.service.*; import com.masterlearning.platform.modules.organization.repository.OrganizationRepository; import com.masterlearning.platform.modules.user.repository.UserRepository; import com.masterlearning.platform.security.util.SecurityUtils; import jakarta.persistence.EntityNotFoundException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class CourseServiceImpl implements CourseService { private final CourseRepository courses; private final OrganizationRepository organizations; private final UserRepository users; public CourseServiceImpl(CourseRepository c,OrganizationRepository o,UserRepository u){courses=c;organizations=o;users=u;} public CourseResponse create(CreateCourseRequest r){if(courses.findBySlug(r.slug()).isPresent())throw new IllegalArgumentException("Course slug already exists"); var org=r.organizationId()==null?null:organizations.findById(r.organizationId()).orElseThrow(()->new EntityNotFoundException("Organization not found")); var user=users.findById(SecurityUtils.getCurrentUserId()).orElseThrow(()->new EntityNotFoundException("Authenticated user not found")); return map(courses.save(new Course(r.title(),r.slug(),r.description(),org,user)));} @Transactional(readOnly=true) public List<CourseResponse> published(){return courses.findByStatus(CourseStatus.PUBLISHED).stream().map(this::map).toList();} public CourseResponse publish(UUID id){var c=courses.findById(id).orElseThrow(()->new EntityNotFoundException("Course not found"));c.publish();return map(c);} private CourseResponse map(Course c){return new CourseResponse(c.getId(),c.getTitle(),c.getSlug(),c.getDescription(),c.getStatus().name(),c.getOrganization()==null?null:c.getOrganization().getId());} }